select location, case when budget >= 4054000 then 'high' when budget >= 937000 then 'mid' else 'low' end budget_bucket, count(*) cnt, count(case when location = 'Chiang Mai' then 1 end) chiang_mai_count from departments where not (location in ('Chiang Mai', 'Bangkok', 'London') and location not in ('Tokyo', 'Berlin', 'Chiang Mai')) group by location, budget_bucket order by chiang_mai_count desc, budget_bucket
